insert into public.prompts (id, family, mode, variant, openness, beats, words_on_screen, stimulus_id, text, status) values
  ('des-t-01', 'describe', 'text', 'place', 'guided', 2, 21, null, 'What did the kitchen look like in the home you grew up in? What''s one specific detail you remember about it?', 'approved'),
  ('des-t-02', 'describe', 'text', 'place', 'guided', 2, 26, null, 'Which room do you spend the most time in? If I had to rebuild it from your description alone, what would I need to get right?', 'approved'),
  ('des-t-03', 'describe', 'text', 'place', 'guided', 2, 27, null, 'A friend is coming to your place for the first time and their phone is dead. Describe your street so they''d know they''re on the right one.', 'draft'),
  ('des-t-04', 'describe', 'text', 'place', 'guided', 2, 26, null, 'You''ve got one free hour and perfect weather. Which outdoor spot near you do you head for, and what can you see from where you sit?', 'approved'),
  ('des-t-05', 'describe', 'text', 'place', 'guided', 2, 24, null, 'You''re sending someone to your usual grocery store with a list of five things. Walk them through the store so they don''t get lost.', 'approved'),
  ('des-t-06', 'describe', 'text', 'place', 'guided', 2, 20, null, 'Picture a classroom you sat in as a kid. Where was your seat, and what could you see from it?', 'approved'),
  ('des-t-07', 'describe', 'text', 'place', 'guided', 2, 23, null, 'If a stranger sat down at your desk or workspace right now, what would they figure out about you from what''s on it?', 'approved'),
  ('des-t-08', 'describe', 'text', 'place', 'guided', 2, 23, null, 'You get to take one out-of-town guest to one restaurant or cafe near you. Where do you go, and what do you recommend?', 'approved'),
  ('des-t-09', 'describe', 'text', 'place', 'guided', 2, 20, null, 'Think of a train station or airport you know well. What would you tell someone to make their life easier?', 'approved'),
  ('des-t-10', 'describe', 'text', 'place', 'guided', 2, 28, null, 'Think of a beach, lake or river you''ve been to more than once. Which spot on it is best for taking photos, and what does it look like?', 'approved'),
  ('des-t-11', 'describe', 'text', 'place', 'guided', 2, 26, null, 'Think of a relative''s house you visited as a kid. What did it smell like, and which room were you not really supposed to go in?', 'approved'),
  ('des-t-12', 'describe', 'text', 'place', 'guided', 2, 24, null, 'You''ve got an afternoon to kill in a bookstore or record store. Which section do you end up in, and what might you buy?', 'approved'),
  ('des-t-13', 'describe', 'text', 'place', 'guided', 2, 27, null, 'Think of a gym, court or field where you''ve spent real time. What does it sound like, and what''s the one thing about it that needs fixing?', 'draft'),
  ('des-t-14', 'describe', 'text', 'place', 'guided', 2, 24, null, 'What can you see from your bedroom window? If you could swap one thing in that view for anything else, what would you change?', 'draft'),
  ('des-t-15', 'describe', 'text', 'place', 'guided', 2, 19, null, 'Think of the last hotel or rental you stayed in. What would your honest review say about the room?', 'draft'),
  ('des-t-16', 'describe', 'text', 'place', 'guided', 2, 28, null, 'Think of a shop that sells basically one kind of thing: a cake shop, a cheese shop, a guitar shop. What''s it like inside, and who shops there?', 'draft'),
  ('des-t-17', 'describe', 'text', 'place', 'guided', 2, 23, null, 'What''s the best venue you''ve ever seen a show in? Tell me what it looked like from where you were standing or sitting.', 'approved'),
  ('des-t-18', 'describe', 'text', 'place', 'guided', 2, 27, null, 'You''re stuck in a waiting room for an hour with a dead phone. Think of a real one you''ve been in: what is there to look at?', 'approved'),
  ('des-t-19', 'describe', 'text', 'place', 'guided', 2, 17, null, 'Think of a playground you knew as a kid. What was the best game you remember playing?', 'approved'),
  ('des-t-20', 'describe', 'text', 'place', 'guided', 2, 27, null, 'You have $20 to spend at a street market or farmers market you know. Walk me past the stalls and tell me what you would pick up.', 'approved'),
  ('des-t-21', 'describe', 'text', 'place', 'guided', 2, 20, null, 'Think of the place you get your hair cut. What do you look at while you''re stuck in the chair?', 'approved'),
  ('des-t-22', 'describe', 'text', 'place', 'guided', 2, 23, null, 'Think of a garage, shed or closet where things go to be forgotten. What''s in there, and what''s the one thing you''d rescue?', 'approved'),
  ('des-t-23', 'describe', 'text', 'place', 'guided', 2, 27, null, 'A film crew wants to shoot one scene in your town or neighborhood. Which street or square do you send them to, and what will they see?', 'approved'),
  ('des-t-24', 'describe', 'text', 'place', 'guided', 2, 26, null, 'You can take one thing home from any museum you''ve visited, no questions asked. What do you take, and what does it look like up close?', 'approved'),
  ('des-t-25', 'describe', 'text', 'place', 'guided', 2, 19, null, 'Think of a trail, campsite or outdoor spot you''d go back to. What''s the view when you get there?', 'approved'),
  ('des-t-26', 'describe', 'text', 'object', 'guided', 2, 21, null, 'What''s the oldest thing you own? If it went missing, how would you describe it so someone could pick it out?', 'approved'),
  ('des-t-27', 'describe', 'text', 'object', 'guided', 2, 23, null, 'What''s one piece of clothing you''d wear every day if nobody noticed? Describe it for me, including what shape it''s in by now.', 'approved'),
  ('des-t-28', 'describe', 'text', 'object', 'guided', 2, 22, null, 'If I emptied the bag or pockets you carry every day onto a table, what would I find? Which item needs explaining?', 'approved'),
  ('des-t-29', 'describe', 'text', 'object', 'guided', 2, 23, null, 'Think of the car, bike or other ride you use most. If you were selling it tomorrow, what would the honest listing say?', 'approved'),
  ('des-t-30', 'describe', 'text', 'object', 'guided', 2, 22, null, 'Everyone has one mug, glass or bowl they reach for first. What does yours look like, and where did it come from?', 'draft'),
  ('des-t-31', 'describe', 'text', 'object', 'guided', 2, 24, null, 'What toy from your childhood would you buy back today if you could? Tell me what it looked like and what it could do.', 'approved'),
  ('des-t-32', 'describe', 'text', 'object', 'guided', 2, 23, null, 'Which piece of furniture in your home has been through the most? Tell me what it looks like and where the damage is.', 'approved'),
  ('des-t-33', 'describe', 'text', 'object', 'guided', 2, 21, null, 'If you could wake up tomorrow able to play any instrument, which one? Describe it as if I''ve never seen one.', 'approved'),
  ('des-t-34', 'describe', 'text', 'object', 'guided', 2, 25, null, 'What''s a tool or gadget you''d replace the same day if it broke? Tell me what it looks like and what you do with it.', 'approved'),
  ('des-t-35', 'describe', 'text', 'object', 'guided', 2, 18, null, 'What''s a gift you''ve held on to for years? Describe it, and tell me where it lives now.', 'approved'),
  ('des-t-36', 'describe', 'text', 'object', 'guided', 2, 17, null, 'If I opened your refrigerator right now, what would I see? What''s been in there the longest?', 'approved'),
  ('des-t-37', 'describe', 'text', 'object', 'guided', 2, 25, null, 'Which pair of your shoes has the most miles on it? Tell me what they look like now compared with the day you got them.', 'approved'),
  ('des-t-38', 'describe', 'text', 'object', 'guided', 2, 29, null, 'Think of a watch, ring or other piece that you or someone close to you wears every day. What does it look like, and where did it come from?', 'draft'),
  ('des-t-39', 'describe', 'text', 'object', 'guided', 2, 25, null, 'Which photo do you have out where people can see it? Tell me what''s in the picture and what was happening just outside the frame.', 'draft'),
  ('des-t-40', 'describe', 'text', 'object', 'guided', 2, 24, null, 'What book or album cover can you picture without looking it up? Describe it well enough that I could find it on a shelf.', 'approved'),
  ('des-t-41', 'describe', 'text', 'object', 'guided', 2, 12, null, 'Without looking, what''s on your phone''s home screen? What''s the organizational method?', 'approved'),
  ('des-t-42', 'describe', 'text', 'object', 'guided', 2, 21, null, 'What game comes out when people are over: a board game, cards, something else? Describe it for someone who''s never played.', 'approved'),
  ('des-t-43', 'describe', 'text', 'object', 'guided', 2, 23, null, 'You can keep only one appliance in your kitchen. Which one survives, and what does it look and sound like when it''s running?', 'approved'),
  ('des-t-44', 'describe', 'text', 'object', 'guided', 2, 30, null, 'Think of a tree or plant you know well: in a yard, on a street, on a windowsill. What does it look like at its best, and at its worst?', 'approved'),
  ('des-t-45', 'describe', 'text', 'object', 'guided', 2, 27, null, 'Think of a pet or an animal you see all the time. If it got loose, how would you describe it so a stranger could spot it?', 'approved'),
  ('des-t-46', 'describe', 'text', 'object', 'guided', 2, 22, null, 'What''s hanging on your walls at home? Pick one thing and tell me what''s in it and why it got the spot.', 'draft'),
  ('des-t-47', 'describe', 'text', 'object', 'guided', 2, 21, null, 'What music do you put on when the weather is at its worst? Describe it to someone who''s never heard it.', 'approved'),
  ('des-t-48', 'describe', 'text', 'object', 'guided', 2, 25, null, 'Which light in your home do you switch on first when it gets dark? Tell me what it looks like and what it lights up.', 'draft'),
  ('des-t-49', 'describe', 'text', 'object', 'guided', 2, 28, null, 'Think of a game controller you use all the time. Which buttons are worn out, and what happened in the game that made you press it so much?', 'approved'),
  ('des-t-50', 'describe', 'text', 'object', 'guided', 2, 24, null, 'Take me through your key ring, one item at a time. What does each key open, and what''s on there that isn''t a key?', 'approved'),
  ('nar-t-01', 'narrate', 'text', 'recount', 'guided', 2, 19, null, 'Tell me about a trip that didn''t go to plan. What went wrong and how did you get home?', 'approved'),
  ('nar-t-02', 'narrate', 'text', 'recount', 'guided', 2, 27, null, 'Think back to your first day at a new job or school. What''s the first thing you remember, and who was the first person you talked to?', 'approved'),
  ('nar-t-03', 'narrate', 'text', 'recount', 'guided', 2, 21, null, 'What''s the worst meal anyone has ever cooked for you? What was on the plate, and did you eat it anyway?', 'approved'),
  ('nar-t-04', 'narrate', 'text', 'recount', 'guided', 2, 22, null, 'Tell me about the last time you lost something you really needed. Where did you look, and did it ever turn up?', 'approved'),
  ('nar-t-05', 'narrate', 'text', 'recount', 'guided', 2, 23, null, 'Tell me about a time you got properly lost. Where were you trying to go, and how did you find your way back?', 'approved'),
  ('nar-t-06', 'narrate', 'text', 'recount', 'guided', 2, 22, null, 'Tell me about a time a stranger did you a favor. What did they do, and what do you remember about them?', 'approved'),
  ('nar-t-07', 'narrate', 'text', 'recount', 'guided', 2, 25, null, 'What''s the best live event you''ve ever been to: a concert, a game, a show? What''s the one moment from it you still think about?', 'approved'),
  ('nar-t-08', 'narrate', 'text', 'recount', 'guided', 2, 19, null, 'Who taught you to drive, or to ride a bike? Tell me about the lesson that went the worst.', 'approved'),
  ('nar-t-09', 'narrate', 'text', 'recount', 'guided', 2, 20, null, 'Tell me about a birthday you won''t forget, yours or someone else''s. What was the plan, and what actually happened?', 'approved'),
  ('nar-t-10', 'narrate', 'text', 'recount', 'guided', 2, 23, null, 'Tell me about a time the weather wrecked your plans. What were you supposed to be doing, and what did you do instead?', 'approved'),
  ('nar-t-11', 'narrate', 'text', 'recount', 'guided', 2, 27, null, 'Tell me about the day you moved into a place you''ve lived. What was the first night like, and what was the first thing to go wrong?', 'approved'),
  ('nar-t-12', 'narrate', 'text', 'recount', 'guided', 2, 28, null, 'Tell me about a game that came down to the very end, one you played in or watched. What was riding on it, and how did it finish?', 'approved'),
  ('nar-t-13', 'narrate', 'text', 'recount', 'guided', 2, 26, null, 'When did a piece of technology last fail you at the worst possible moment? What were you in the middle of, and how did you recover?', 'approved'),
  ('nar-t-14', 'narrate', 'text', 'recount', 'guided', 2, 23, null, 'Think of someone important to you who isn''t family. Where did you first meet, and what did you make of them that day?', 'approved'),
  ('nar-t-15', 'narrate', 'text', 'recount', 'guided', 2, 22, null, 'Tell me about a small mistake that snowballed. What was the mistake, and how far did it get before someone caught it?', 'approved'),
  ('nar-t-16', 'narrate', 'text', 'recount', 'guided', 2, 20, null, 'What''s the worst travel delay you''ve ever sat through? Where were you stuck, and how did you pass the time?', 'approved'),
  ('nar-t-17', 'narrate', 'text', 'recount', 'guided', 2, 22, null, 'What was the first concert or show you ever went to? Who took you, and what do you remember about the room?', 'approved'),
  ('nar-t-18', 'narrate', 'text', 'recount', 'guided', 2, 23, null, 'Tell me about a time something broke at home at a bad moment. What gave out, and who ended up dealing with it?', 'approved'),
  ('nar-t-19', 'narrate', 'text', 'recount', 'guided', 2, 25, null, 'Tell me about a surprise you planned, or one that was sprung on you. How was it kept secret, and what happened at the reveal?', 'approved'),
  ('nar-t-20', 'narrate', 'text', 'recount', 'guided', 2, 20, null, 'Tell me about a time you were spectacularly late. What were you late for, and what excuse did you give?', 'approved'),
  ('nar-t-21', 'narrate', 'text', 'recount', 'guided', 2, 23, null, 'Tell me about one holiday meal you remember better than the others. Who was at the table, and what made that year different?', 'approved'),
  ('nar-t-22', 'narrate', 'text', 'recount', 'guided', 2, 20, null, 'What''s the first thing you ever cooked for other people? How did it come out, and what did they say?', 'approved'),
  ('nar-t-23', 'narrate', 'text', 'recount', 'guided', 2, 22, null, 'Tell me about a game or match you saw in person. Where were you sitting, and what''s the play you remember best?', 'approved'),
  ('nar-t-24', 'narrate', 'text', 'recount', 'guided', 2, 26, null, 'Tell me about a time an animal outsmarted you: a pet, a pigeon, a raccoon. What did it do, and what did you do about it?', 'approved'),
  ('nar-t-25', 'narrate', 'text', 'recount', 'guided', 2, 24, null, 'Tell me about your first week in a new city or neighborhood. What did you have to figure out, and where did you eat?', 'approved'),
  ('nar-t-26', 'narrate', 'text', 'recount', 'guided', 2, 22, null, 'Where did your school take you on trips? Tell me about the one you remember best, and what happened on the bus.', 'approved'),
  ('nar-t-27', 'narrate', 'text', 'recount', 'guided', 2, 18, null, 'When was the last time you got locked out of somewhere? How did you finally get back in?', 'approved'),
  ('nar-t-28', 'narrate', 'text', 'recount', 'guided', 2, 24, null, 'What''s the best wedding or big party you''ve ever been to? What made it better than the rest, and how late did you stay?', 'approved'),
  ('nar-t-29', 'narrate', 'text', 'recount', 'guided', 2, 23, null, 'What''s the best thing you ever bought that you absolutely did not need? Tell me about the moment you decided to get it.', 'approved'),
  ('nar-t-30', 'narrate', 'text', 'recount', 'guided', 2, 18, null, 'When did directions last send you somewhere wrong? Where did you end up, and whose fault was it?', 'approved'),
  ('nar-t-31', 'narrate', 'text', 'recount', 'guided', 2, 19, null, 'Where''s the strangest place you''ve ever fallen asleep? How did you end up there, and how did you sleep?', 'approved'),
  ('nar-t-32', 'narrate', 'text', 'recount', 'guided', 2, 22, null, 'Tell me about your first time on a plane or a boat. Where were you headed, and what surprised you about it?', 'approved'),
  ('nar-t-33', 'narrate', 'text', 'recount', 'guided', 2, 23, null, 'Tell me about a prank that worked, or one that went too far. Who was the target, and how did they take it?', 'approved'),
  ('nar-t-34', 'narrate', 'text', 'recount', 'guided', 2, 24, null, 'When did the power last go out on you? What were you doing when it happened, and how did you spend the hours after?', 'approved'),
  ('nar-t-35', 'narrate', 'text', 'recount', 'guided', 2, 20, null, 'Tell me about a group project that nearly fell apart. What was your job, and how did it get finished?', 'approved'),
  ('nar-t-36', 'narrate', 'text', 'recount', 'guided', 2, 17, null, 'What was your first job? Tell me about the boss, and about one shift you still remember.', 'draft'),
  ('nar-t-37', 'narrate', 'text', 'recount', 'guided', 2, 22, null, 'What''s something you''ve won: a raffle, a trophy, a bet? Tell me how you won it and what happened to the prize.', 'approved'),
  ('nar-t-38', 'narrate', 'text', 'recount', 'guided', 2, 25, null, 'Tell me about a time you spoke in front of a crowd. What was the occasion, and what do you remember about the first minute?', 'approved'),
  ('nar-t-39', 'narrate', 'text', 'recount', 'guided', 2, 24, null, 'Tell me about the worst haircut you''ve ever had. How did you know it was no good, and how long before you fixed it?', 'approved'),
  ('nar-t-40', 'narrate', 'text', 'recount', 'guided', 2, 21, null, 'What''s the best road trip you''ve taken? Who was in the car, and what was the best stop along the way?', 'approved'),
  ('nar-t-41', 'narrate', 'text', 'recount', 'guided', 2, 20, null, 'What''s something a kid once said that you''ve never forgotten? Who was the kid, and how did the adults react?', 'approved'),
  ('nar-t-42', 'narrate', 'text', 'recount', 'guided', 2, 23, null, 'Tell me about a whole day you spent outside. Where were you, and what shape were you in by the end of it?', 'approved'),
  ('nar-t-43', 'narrate', 'text', 'recount', 'guided', 2, 21, null, 'Who''s someone you ran into after years of not seeing them? Where were you, and what did you two talk about?', 'approved'),
  ('nar-t-44', 'narrate', 'text', 'recount', 'guided', 2, 22, null, 'Tell me about something you fixed with no idea what you were doing. What was broken, and has it broken again since?', 'approved'),
  ('nar-t-45', 'narrate', 'text', 'recount', 'guided', 2, 24, null, 'Tell me about your first meal in a place you''d never been before. Where were you, and how did you decide what to order?', 'approved'),
  ('nar-t-46', 'narrate', 'text', 'recount', 'guided', 2, 21, null, 'What''s the longest you''ve ever waited in a line? What was at the end of it, and was it worth it?', 'approved'),
  ('nar-t-47', 'narrate', 'text', 'recount', 'guided', 2, 25, null, 'Tell me about a time you got caught in rain or snow. Where were you headed, and what did you look like when you arrived?', 'approved'),
  ('nar-t-48', 'narrate', 'text', 'recount', 'guided', 2, 17, null, 'Tell me about a celebration that almost didn''t happen. What nearly stopped it, and who rescued it?', 'approved'),
  ('nar-t-49', 'narrate', 'text', 'recount', 'guided', 2, 25, null, 'Tell me about an order or delivery that showed up wrong. What did you ask for, what arrived, and what did you do about it?', 'approved'),
